// Package feeledger is a pure accounting primitive for realms that hold
// coins on behalf of users and charge an explicit protocol fee on
// deposits. It tracks per-account balances, the sum of user liabilities,
// and a separately-accrued fee pot. It never touches coins itself: the
// importing realm moves coins and drives this ledger, keeping the two in
// lock-step so that
//
//	coins held by realm == UsersTotal() + FeesAccrued() + surplus
//
// where surplus is coins pushed to the realm outside the ledger's flow
// (always >= 0, and 0 if every coin movement goes through the ledger).
//
// Fee model:
//   - Fees are expressed in basis points (1 bps = 0.01%); BpsDenominator
//     is 10000, so bps == 10000 means the whole deposit is fee.
//   - fee = floor(amount * bps / 10000). Rounding always favors the
//     DEPOSITOR: any fractional fee is dropped, the account is credited
//     amount - fee. A small deposit may therefore pay zero fee.
//   - There is no minimum fee. The maximum fee is bounded by the
//     per-ledger cap set at construction (maxFeeBps <= 10000), so a fee
//     can never exceed its deposit.
//   - bps == 0 is a valid configuration: fee is exactly 0 and the full
//     amount is credited.
//
// All failures are returned as errors and leave the ledger COMPLETELY
// UNCHANGED; callers in realms typically wrap calls so an error panics
// and aborts the transaction. Must* wrappers are provided and are the
// only functions in this package that panic.
//
// The ledger is address-agnostic: accounts are non-empty strings. Realms
// normally use address.String().
package feeledger

import (
	"errors"

	"gno.land/p/nt/avl/v0"
)

// BpsDenominator is the fee basis: fees are bps/BpsDenominator of the
// deposited amount.
const BpsDenominator = int64(10000)

// Errors returned by Ledger operations.
var (
	ErrEmptyAccount  = errors.New("feeledger: empty account key")
	ErrInvalidAmount = errors.New("feeledger: amount must be positive")
	ErrInvalidBps    = errors.New("feeledger: fee bps out of range")
	ErrInsufficient  = errors.New("feeledger: insufficient balance")
	ErrOverflow      = errors.New("feeledger: int64 overflow")
)

// Ledger tracks per-account balances, their sum (user liabilities), and
// separately-accrued protocol fees. The zero value is not usable;
// construct with New.
type Ledger struct {
	maxFeeBps   int64
	balances    *avl.Tree // account string -> int64 (always > 0)
	usersTotal  int64     // == sum of all balances
	feesAccrued int64     // fees charged but not yet withdrawn
}

// New returns an empty ledger that rejects deposit fees above maxFeeBps.
// maxFeeBps must be in [0, BpsDenominator].
func New(maxFeeBps int64) (*Ledger, error) {
	if maxFeeBps < 0 || maxFeeBps > BpsDenominator {
		return nil, ErrInvalidBps
	}
	return &Ledger{
		maxFeeBps: maxFeeBps,
		balances:  avl.NewTree(),
	}, nil
}

// MustNew is New but panics on error.
func MustNew(maxFeeBps int64) *Ledger {
	l, err := New(maxFeeBps)
	if err != nil {
		panic(err)
	}
	return l
}

// MaxFeeBps returns the ledger's hard fee cap.
func (l *Ledger) MaxFeeBps() int64 {
	return l.maxFeeBps
}

// FeeFor returns the fee charged on amount at bps, using the ledger's
// rounding rule: floor(amount * bps / BpsDenominator). It is a pure
// preview — no state is read or written beyond validation against
// BpsDenominator (NOT the ledger cap; use it to inspect any policy).
// amount must be >= 0 and bps in [0, BpsDenominator].
func FeeFor(amount, bps int64) (int64, error) {
	if amount < 0 {
		return 0, ErrInvalidAmount
	}
	if bps < 0 || bps > BpsDenominator {
		return 0, ErrInvalidBps
	}
	return feeFor(amount, bps), nil
}

// feeFor computes floor(amount*bps/BpsDenominator) without intermediate
// overflow: amount = q*BpsDenominator + r, so the fee is
// q*bps + floor(r*bps/BpsDenominator). q*bps <= amount because
// bps <= BpsDenominator, and r*bps < BpsDenominator^2 (10^8), so every
// intermediate fits comfortably in int64. Inputs must be pre-validated.
func feeFor(amount, bps int64) int64 {
	q := amount / BpsDenominator
	r := amount % BpsDenominator
	return q*bps + r*bps/BpsDenominator
}

// Deposit credits account with amount minus the fee at feeBps, accruing
// the fee to the fee pot. Returns the credited amount and the fee
// (credited + fee == amount always). Fails with ErrEmptyAccount,
// ErrInvalidAmount (amount <= 0), ErrInvalidBps (feeBps outside
// [0, MaxFeeBps]), or ErrOverflow if the account balance or total
// liabilities would leave int64 range. On error nothing is modified.
func (l *Ledger) Deposit(account string, amount, feeBps int64) (credited, fee int64, err error) {
	if account == "" {
		return 0, 0, ErrEmptyAccount
	}
	if amount <= 0 {
		return 0, 0, ErrInvalidAmount
	}
	if feeBps < 0 || feeBps > l.maxFeeBps {
		return 0, 0, ErrInvalidBps
	}

	fee = feeFor(amount, feeBps)
	credited = amount - fee // >= 0; > 0 whenever feeBps < BpsDenominator

	newBalance, ok := checkedAdd(l.BalanceOf(account), credited)
	if !ok {
		return 0, 0, ErrOverflow
	}
	newUsersTotal, ok := checkedAdd(l.usersTotal, credited)
	if !ok {
		return 0, 0, ErrOverflow
	}
	newFeesAccrued, ok := checkedAdd(l.feesAccrued, fee)
	if !ok {
		return 0, 0, ErrOverflow
	}
	// Total liabilities must stay representable as one int64, since they
	// mirror a single coin balance held by the importing realm.
	if _, ok := checkedAdd(newUsersTotal, newFeesAccrued); !ok {
		return 0, 0, ErrOverflow
	}

	if newBalance > 0 {
		l.balances.Set(account, newBalance)
	}
	l.usersTotal = newUsersTotal
	l.feesAccrued = newFeesAccrued
	return credited, fee, nil
}

// MustDeposit is Deposit but panics on error.
func (l *Ledger) MustDeposit(account string, amount, feeBps int64) (credited, fee int64) {
	credited, fee, err := l.Deposit(account, amount, feeBps)
	if err != nil {
		panic(err)
	}
	return credited, fee
}

// Withdraw debits amount from account. Fails with ErrEmptyAccount,
// ErrInvalidAmount (amount <= 0), or ErrInsufficient if the balance is
// smaller than amount. A balance drained to zero is removed from
// storage. On error nothing is modified.
func (l *Ledger) Withdraw(account string, amount int64) error {
	if account == "" {
		return ErrEmptyAccount
	}
	if amount <= 0 {
		return ErrInvalidAmount
	}
	balance := l.BalanceOf(account)
	if balance < amount {
		return ErrInsufficient
	}
	if balance == amount {
		l.balances.Remove(account)
	} else {
		l.balances.Set(account, balance-amount)
	}
	// usersTotal >= balance >= amount by the sum invariant, so this
	// cannot underflow.
	l.usersTotal -= amount
	return nil
}

// MustWithdraw is Withdraw but panics on error.
func (l *Ledger) MustWithdraw(account string, amount int64) {
	if err := l.Withdraw(account, amount); err != nil {
		panic(err)
	}
}

// WithdrawAll drains account's entire balance and returns it. Returns
// (0, nil) if the account holds nothing. Fails only with
// ErrEmptyAccount.
func (l *Ledger) WithdrawAll(account string) (int64, error) {
	if account == "" {
		return 0, ErrEmptyAccount
	}
	balance := l.BalanceOf(account)
	if balance == 0 {
		return 0, nil
	}
	l.balances.Remove(account)
	l.usersTotal -= balance
	return balance, nil
}

// WithdrawFees drains the accrued fee pot and returns the amount
// (0 if nothing has accrued). Never fails.
func (l *Ledger) WithdrawFees() int64 {
	fees := l.feesAccrued
	l.feesAccrued = 0
	return fees
}

// BalanceOf returns account's balance, or 0 if absent.
func (l *Ledger) BalanceOf(account string) int64 {
	v := l.balances.Get(account)
	if v == nil {
		return 0
	}
	return v.(int64)
}

// UsersTotal returns the sum of all account balances (user liabilities).
func (l *Ledger) UsersTotal() int64 {
	return l.usersTotal
}

// FeesAccrued returns the fee pot: charged but not yet withdrawn.
func (l *Ledger) FeesAccrued() int64 {
	return l.feesAccrued
}

// Liabilities returns UsersTotal() + FeesAccrued() — everything the
// importing realm owes. Deposit guarantees this sum fits in int64.
func (l *Ledger) Liabilities() int64 {
	return l.usersTotal + l.feesAccrued
}

// Accounts returns the number of accounts with a non-zero balance.
func (l *Ledger) Accounts() int {
	return l.balances.Size()
}

// Iterate calls fn for each account in sorted order with its balance.
// Iteration stops early when fn returns true.
func (l *Ledger) Iterate(fn func(account string, balance int64) bool) {
	l.balances.Iterate("", "", func(key string, value any) bool {
		return fn(key, value.(int64))
	})
}

// checkedAdd returns a+b and reports whether the addition did not
// overflow int64.
func checkedAdd(a, b int64) (int64, bool) {
	sum := a + b
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

// Realm vault holds GNOT deposits with per-user balances and an
// explicit, inspectable protocol fee, built on
// gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger.
//
// Flow: an EOA deposits GNOT by calling Deposit with coins attached
// (`-send`); the configured fee (FeeBps, capped at MaxFeeBps) accrues to
// a separate fee pot and the remainder credits the depositor's balance.
// Users claim their balance back at any time, partially or fully. The
// fee recipient — a role distinct from the admin — withdraws the fee
// pot.
//
// FEE MODEL (all values inspectable via FeeBps/FeeRecipient/MaxFeeBps):
//   - fee = floor(amount * FeeBps / 10000); rounding favors the
//     depositor; no minimum fee (small deposits may pay 0).
//   - FeeBps starts at 0 (no fee) and is changed only by the admin via
//     SetFeeBps, hard-capped at MaxFeeBps (10% — the cap itself is a
//     compile-time constant and cannot be raised by anyone).
//   - A fee change applies to FUTURE deposits only; already-accrued fees
//     and user balances are untouched.
//   - Fees accrue to a pot, not an address. Changing the fee recipient
//     re-points who may withdraw the pot, INCLUDING what was accrued
//     under the previous recipient (positional, documented trade-off).
//   - With FeeBps == 0 deposits credit in full and the pot grows by 0.
//   - The fee can never exceed the deposit: FeeBps <= 10000 structurally
//     and <= 1000 by this realm's cap.
//
// ACCOUNTING INVARIANT (conservation): let H be the ugnot held at this
// realm's address, U the sum of user balances, F the accrued fee pot.
// At every transaction boundary:
//
//	H == U + F + S,  S >= 0
//
// where S (surplus) is ugnot pushed to the realm address outside
// Deposit (e.g. a direct bank send). S stays 0 if all coins arrive via
// Deposit. Derivation from chain semantics: (1) a MsgCall `-send`
// envelope is transferred to the realm address BEFORE the call body
// runs, and Deposit's IsUserCall guard is exactly the case where that
// receipt is guaranteed, so Deposit raises U+F by the amount already
// added to H; (2) Claim/WithdrawFees debit the ledger first, then move
// the identical amount out via a RealmSend banker, lowering H and U+F
// equally; (3) any panic aborts the whole transaction, reverting ledger
// and coin movements together (atomicity); (4) this realm never uses
// IssueCoin/RemoveCoin. Surplus is intentionally unreachable: it can
// only be swept by the fee recipient via SweepSurplus, never counted as
// a user balance.
//
// ONLY GNOT: Deposit rejects any transaction whose send envelope is not
// exactly one ugnot coin. Other assets force-sent to the realm address
// are not accepted, not tracked, and sit in surplus.
package vault

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger"
)

// Denom is the only asset this vault accepts.
const Denom = "ugnot"

// MaxFeeBps is the hard protocol-fee cap: 1000 bps = 10%. Nobody can
// configure a higher fee; changing this requires deploying a new realm.
const MaxFeeBps = int64(1000)

var (
	admin        address // may set fee, fee recipient, and successor admin
	feeRecipient address // may withdraw the fee pot and sweep surplus
	feeBps       int64   // current protocol fee in basis points

	self   address // this realm's own address, captured at deploy
	ledger = feeledger.MustNew(MaxFeeBps)
)

func init() {
	admin = unsafe.OriginCaller() // the deployer
	feeRecipient = admin
	self = unsafe.CurrentRealm().Address()
}

// Deposit credits the caller with the attached GNOT minus the current
// protocol fee. Only direct EOA calls (maketx call with -send) are
// accepted: that is the only shape where the chain guarantees the send
// envelope landed at this realm's address before the body runs. The
// envelope must be exactly one coin of denom ugnot with positive
// amount.
func Deposit(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("deposit must be a direct EOA call with -send (realms and maketx-run are rejected)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != Denom {
		panic("send exactly one coin type: " + Denom)
	}
	amount := sent[0].Amount
	if amount <= 0 {
		panic("deposit amount must be positive")
	}

	depositor := cur.Previous().Address()
	credited, fee, err := ledger.Deposit(depositor.String(), amount, feeBps)
	if err != nil {
		panic(err)
	}
	chain.Emit("Deposit",
		"from", depositor.String(),
		"amount", itoa(amount),
		"credited", itoa(credited),
		"fee", itoa(fee),
	)
}

// Claim sends amount ugnot of the caller's balance back to the caller.
// Fails if amount is not positive or exceeds the caller's balance.
func Claim(cur realm, amount int64) {
	caller := cur.Previous().Address()
	if err := ledger.Withdraw(caller.String(), amount); err != nil {
		panic(err)
	}
	send(cur, caller, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// ClaimAll sends the caller's entire balance back to the caller. Fails
// if the caller has no balance.
func ClaimAll(cur realm) {
	caller := cur.Previous().Address()
	amount, err := ledger.WithdrawAll(caller.String())
	if err != nil {
		panic(err)
	}
	if amount == 0 {
		panic("nothing to claim")
	}
	send(cur, caller, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// WithdrawFees sends the entire accrued fee pot to the fee recipient.
// Only the fee recipient may call it. Fails if the pot is empty.
func WithdrawFees(cur realm) {
	caller := cur.Previous().Address()
	if caller != feeRecipient {
		panic("only the fee recipient may withdraw fees")
	}
	amount := ledger.WithdrawFees()
	if amount == 0 {
		panic("no fees accrued")
	}
	send(cur, feeRecipient, amount)
	chain.Emit("FeesWithdrawn", "to", feeRecipient.String(), "amount", itoa(amount))
}

// SweepSurplus sends coins that sit at the realm address ABOVE the
// ledger's liabilities (ugnot force-sent outside Deposit, or any other
// denomination) to the fee recipient. Only the fee recipient may call
// it. User balances and the fee pot are untouchable by construction:
// only the excess over Liabilities() moves. Fails if there is no
// surplus.
func SweepSurplus(cur realm) {
	caller := cur.Previous().Address()
	if caller != feeRecipient {
		panic("only the fee recipient may sweep surplus")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	held := bk.GetCoins(self)
	var out chain.Coins
	for _, c := range held {
		if c.Denom == Denom {
			surplus := c.Amount - ledger.Liabilities()
			if surplus > 0 {
				out = append(out, chain.NewCoin(Denom, surplus))
			}
			continue
		}
		if c.Amount > 0 {
			out = append(out, c)
		}
	}
	if len(out) == 0 {
		panic("no surplus to sweep")
	}
	bk.SendCoins(self, feeRecipient, out)
	chain.Emit("SurplusSwept", "to", feeRecipient.String(), "coins", out.String())
}

// SweepDenom sends the surplus of a single denomination to the fee
// recipient. This is the bounded escape hatch for when SweepSurplus
// would exceed gas because a third party force-sent many junk
// denominations to the realm address: each call touches exactly one
// denomination, so ugnot surplus can always be recovered regardless of
// how many foreign denoms accumulate. For ugnot only the excess over
// Liabilities() moves; any other denom moves wholly. Only the fee
// recipient may call it.
func SweepDenom(cur realm, denom string) {
	caller := cur.Previous().Address()
	if caller != feeRecipient {
		panic("only the fee recipient may sweep surplus")
	}
	if denom == "" {
		panic("empty denom")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	amount := bk.GetCoin(self, denom)
	if denom == Denom {
		amount -= ledger.Liabilities()
	}
	if amount <= 0 {
		panic("no surplus to sweep for " + denom)
	}
	bk.SendCoins(self, feeRecipient, chain.Coins{chain.NewCoin(denom, amount)})
	chain.Emit("SurplusSwept", "to", feeRecipient.String(), "coins", itoa(amount)+denom)
}

// SetFeeBps sets the protocol fee for FUTURE deposits. Admin only;
// bounded by [0, MaxFeeBps].
func SetFeeBps(cur realm, bps int64) {
	assertAdmin(cur.Previous().Address())
	if bps < 0 || bps > MaxFeeBps {
		panic("fee bps out of range [0, " + itoa(MaxFeeBps) + "]")
	}
	old := feeBps
	feeBps = bps
	chain.Emit("FeeBpsChanged", "old", itoa(old), "new", itoa(bps))
}

// SetFeeRecipient re-points who may withdraw the fee pot (including
// fees accrued before the change) and sweep surplus. Admin only; the
// zero address is rejected.
func SetFeeRecipient(cur realm, next address) {
	assertAdmin(cur.Previous().Address())
	var zero address
	if next == zero {
		panic("empty fee recipient")
	}
	old := feeRecipient
	feeRecipient = next
	chain.Emit("FeeRecipientChanged", "old", old.String(), "new", next.String())
}

// TransferAdmin hands the admin role to next. Admin only; the zero
// address is rejected. One-step: a transfer to a wrong-but-valid
// address permanently loses fee administration (deposits and claims
// keep working).
func TransferAdmin(cur realm, next address) {
	assertAdmin(cur.Previous().Address())
	var zero address
	if next == zero {
		panic("empty admin address")
	}
	admin = next
	chain.Emit("AdminTransferred", "newAdmin", next.String())
}

// --- read-only views ---

// Admin returns the current admin.
func Admin() address { return admin }

// FeeRecipient returns who may withdraw the fee pot.
func FeeRecipient() address { return feeRecipient }

// FeeBps returns the protocol fee applied to future deposits, in basis
// points of the deposit amount.
func FeeBps() int64 { return feeBps }

// FeeOn previews the fee and credited amount for a deposit of amount at
// the CURRENT FeeBps.
func FeeOn(amount int64) (fee, credited int64) {
	f, err := feeledger.FeeFor(amount, feeBps)
	if err != nil {
		panic(err)
	}
	return f, amount - f
}

// BalanceOf returns addr's claimable balance.
func BalanceOf(addr address) int64 { return ledger.BalanceOf(addr.String()) }

// UsersTotal returns the sum of all user balances.
func UsersTotal() int64 { return ledger.UsersTotal() }

// FeesAccrued returns the fee pot awaiting withdrawal.
func FeesAccrued() int64 { return ledger.FeesAccrued() }

// Liabilities returns UsersTotal() + FeesAccrued().
func Liabilities() int64 { return ledger.Liabilities() }

// Held returns the ugnot actually held at the realm address.
func Held() int64 {
	return banker.NewReadonlyBanker().GetCoin(self, Denom)
}

// Surplus returns Held() - Liabilities(): ugnot at the realm address
// that the ledger does not owe to anyone. Negative would indicate a
// conservation bug (see the invariant in the package doc).
func Surplus() int64 { return Held() - ledger.Liabilities() }

// Address returns this realm's own address (the deposit target).
func Address() address { return self }

// Render shows configuration, totals, and the live conservation check.
func Render(_ string) string {
	held := Held()
	liab := ledger.Liabilities()
	status := "OK"
	if held < liab {
		status = "VIOLATED"
	}
	out := "# Vault\n\n"
	out += "GNOT deposits with per-user balances and an explicit protocol fee.\n\n"
	out += "## Fee configuration\n\n"
	out += "- fee: " + itoa(feeBps) + " bps (cap " + itoa(MaxFeeBps) + " bps)\n"
	out += "- fee recipient: " + feeRecipient.String() + "\n"
	out += "- admin: " + admin.String() + "\n\n"
	out += "## Accounting\n\n"
	out += "- users total: " + itoa(ledger.UsersTotal()) + Denom + "\n"
	out += "- fees accrued: " + itoa(ledger.FeesAccrued()) + Denom + "\n"
	out += "- held: " + itoa(held) + Denom + "\n"
	out += "- accounts: " + strconv.Itoa(ledger.Accounts()) + "\n"
	out += "- conservation (held >= users+fees): " + status + "\n"
	return out
}

// --- internals ---

// assertAdmin gates admin-only entrypoints; callers resolve identity at
// the crossing boundary and pass the address down.
func assertAdmin(caller address) {
	if caller != admin {
		panic("admin only")
	}
}

// send moves amount ugnot from the realm to `to`. Callers must have
// debited the ledger first (checks-effects-interactions); a panic here
// aborts the transaction, reverting the debit with it.
func send(cur realm, to address, amount int64) {
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(self, to, chain.Coins{chain.NewCoin(Denom, amount)})
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

// Realm cointest is a throwaway deployment-validation helper for the
// vault realm. It creates the two out-of-band conditions the vault's
// surplus machinery must handle — a direct bank send of ugnot and a
// foreign denomination — and exercises the vault's realm-caller
// rejection. Not part of the product; safe to abandon after validation.
package cointest

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"

	vault "gno.land/r/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/vault"
)

var issued string // chain-qualified denom minted by MintAndSend

// ForwardUgnot forwards the ugnot attached to this call to target via a
// plain bank send — out-of-band relative to target's own deposit flow.
func ForwardUgnot(cur realm, target address) {
	if !cur.Previous().IsUserCall() {
		panic("EOA only")
	}
	sent := unsafe.OriginSend()
	if len(sent) == 0 {
		panic("attach coins to forward")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(cur.Address(), target, sent)
}

// MintAndSend issues amount of this realm's own denomination and
// force-sends it to target, recording the chain-qualified denom.
func MintAndSend(cur realm, target address, amount int64) {
	if amount <= 0 {
		panic("amount must be positive")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmIssue, cur)
	bk.IssueCoin(cur.Address(), "junk", amount)
	for _, c := range bk.GetCoins(cur.Address()) {
		if c.Denom != "ugnot" {
			issued = c.Denom
			bk.SendCoins(cur.Address(), target, chain.Coins{c})
			return
		}
	}
	panic("no issued denom found")
}

// Issued returns the denom minted by MintAndSend.
func Issued() string { return issued }

// TryDeposit attempts a realm-to-realm call of vault.Deposit. The vault
// must reject it (IsUserCall guard), aborting this whole transaction —
// success of this function would be a security regression.
func TryDeposit(cur realm) {
	vault.Deposit(cross(cur))
}

// Realm cointest2 corrects cointest's MintAndSend: on-chain, IssueCoin
// requires the fully-qualified denom "/<pkgpath>:<sub>" (the local test
// harness accepted a bare subdenom — documented harness/chain
// discrepancy). Throwaway validation helper; safe to abandon.
package cointest2

import (
	"chain"
	"chain/banker"
)

// FullDenom is the chain-qualified denomination this realm issues.
const FullDenom = "/gno.land/r/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/cointest2:junk"

// MintAndSend issues amount of FullDenom and force-sends it to target.
func MintAndSend(cur realm, target address, amount int64) {
	if amount <= 0 {
		panic("amount must be positive")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmIssue, cur)
	bk.IssueCoin(cur.Address(), FullDenom, amount)
	bk.SendCoins(cur.Address(), target, chain.Coins{chain.NewCoin(FullDenom, amount)})
}

// Realm bounties is a GNOT bounty board that COMPOSES the reusable
// accounting package gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger
// instead of re-implementing balance accounting.
//
// STATE OWNERSHIP (the dependency boundary):
//   - This realm owns the bounty state machine: bounty records (funder,
//     title, amount, status, winner), the sum of open escrow
//     (openTotal), and per-bounty funder authorization.
//   - feeledger owns all claimable-balance accounting: per-account
//     balances, the protocol-fee pot, fee rounding, overflow checks,
//     and withdraw arithmetic. This realm never duplicates that logic;
//     it only calls the ledger API and panics on its errors.
//
// LIFECYCLE:
//
//	CreateBounty (EOA + -send)  : escrow -> openTotal, status Open
//	Award (funder only)         : openTotal -> ledger.Deposit(winner,
//	                              amount, snapshot fee)
//	Cancel (funder only)        : openTotal -> ledger.Deposit(funder,
//	                              amount, 0)       [no fee on refund]
//	Claim / ClaimAll (anyone)   : pays out the caller's ledger balance
//	WithdrawFees (fee recipient): pays out the fee pot
//
// Awarded and Cancelled are terminal; a bounty transitions exactly once.
//
// FEE MODEL: fee = floor(amount * bps / 10000), rounding favors the
// recipient, no minimum fee, admin-settable up to the compile-time
// MaxFeeBps cap, accrued to a pot withdrawable by the fee recipient
// role. The applicable bps is SNAPSHOTTED INTO THE BOUNTY AT CREATION
// and charged at Award: the funder commits to the fee they saw, and a
// later SetFeeBps affects only bounties created afterwards (this
// closes the admin front-run found in the composition audit). Refunds
// via Cancel are always fee-free. A failed Award (e.g. ledger
// overflow) leaves the bounty Open — the funder can retry or Cancel.
//
// COMPOSED ACCOUNTING INVARIANT: let H be ugnot held at this realm's
// address, B = openTotal (application escrow), U+F the ledger's
// liabilities, S >= 0 out-of-band surplus. At every transaction
// boundary:
//
//	H == B + U + F + S
//
// Derivation: CreateBounty raises H and B equally (the IsUserCall +
// envelope guard is the receipt-guaranteed shape, validated live on
// pearl-1); Award/Cancel move amount from B into U+F within one
// transaction, and feeledger guarantees credited + fee == amount;
// Claim/WithdrawFees debit the ledger before sending the identical
// amount (checks-effects-interactions), lowering H and U+F equally;
// any panic aborts the whole transaction; this realm never issues or
// removes coins. The application invariant B == Σ amount(Open) is
// maintained in lockstep with every status transition.
//
// ONLY GNOT: CreateBounty rejects any envelope that is not exactly one
// positive ugnot coin. Foreign denominations force-sent to the realm
// sit in surplus and are recoverable via SweepDenom (fee recipient
// only), which never touches B, U, or F.
package bounties

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger"
	"gno.land/p/nt/avl/v0"
)

// Denom is the only asset this realm accepts.
const Denom = "ugnot"

// MaxFeeBps is the hard protocol-fee cap: 1000 bps = 10%.
const MaxFeeBps = int64(1000)

// Bounty status values.
const (
	StatusOpen      = "open"
	StatusAwarded   = "awarded"
	StatusCancelled = "cancelled"
)

const maxTitleLen = 80

// Bounty is one bounty record. Fields are unexported; read access goes
// through BountyInfo so no interior pointers escape the realm.
type bounty struct {
	id     int64
	funder address
	title  string
	amount int64
	feeBps int64 // fee policy snapshotted at creation, charged at Award
	status string
	winner address // set iff status == StatusAwarded
}

var (
	admin        address // may set fee, fee recipient, successor admin
	feeRecipient address // may withdraw fees and sweep surplus
	feeBps       int64   // protocol fee snapshotted into new bounties

	self      address // this realm's address, captured at deploy
	nextID    int64   // next bounty id (first bounty gets id 1)
	openTotal int64   // == Σ amount over bounties with status Open

	bounties = avl.NewTree() // padID(id) -> *bounty
	ledger   = feeledger.MustNew(MaxFeeBps)
)

func init() {
	admin = unsafe.OriginCaller()
	feeRecipient = admin
	self = unsafe.CurrentRealm().Address()
}

// CreateBounty escrows the attached GNOT as a new open bounty and
// returns its id. Only direct EOA calls with -send are accepted (the
// receipt-guaranteed shape). The envelope must be exactly one positive
// ugnot coin. The caller becomes the bounty's funder.
func CreateBounty(cur realm, title string) int64 {
	if !cur.Previous().IsUserCall() {
		panic("bounty creation must be a direct EOA call with -send")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != Denom {
		panic("send exactly one coin type: " + Denom)
	}
	amount := sent[0].Amount
	if amount <= 0 {
		panic("bounty amount must be positive")
	}
	assertValidTitle(title)

	newOpenTotal, ok := checkedAdd(openTotal, amount)
	if !ok {
		panic("open escrow overflow")
	}

	funder := cur.Previous().Address()
	nextID++
	b := &bounty{
		id:     nextID,
		funder: funder,
		title:  title,
		amount: amount,
		feeBps: feeBps, // snapshot: later SetFeeBps cannot change this bounty's fee
		status: StatusOpen,
	}
	bounties.Set(padID(b.id), b)
	openTotal = newOpenTotal

	chain.Emit("BountyCreated",
		"id", itoa(b.id),
		"funder", funder.String(),
		"amount", itoa(amount),
		"feeBps", itoa(b.feeBps),
	)
	return b.id
}

// Award closes an open bounty in favor of winner: the escrowed amount
// leaves the open pool and is credited to winner's claimable balance
// through the ledger, charging the fee snapshotted at creation. Only
// the bounty's funder may award it. Terminal: an awarded bounty can
// never change again.
func Award(cur realm, id int64, winner address) {
	caller := cur.Previous().Address()
	b := mustGetBounty(id)
	if caller != b.funder {
		panic("only the bounty funder may award")
	}
	if b.status != StatusOpen {
		panic("bounty is not open")
	}
	var zero address
	if winner == zero {
		panic("empty winner address")
	}

	// Move the escrow from application state into ledger liabilities in
	// one transaction, at the fee snapshotted when the bounty was
	// created. feeledger validates before mutating and guarantees
	// credited + fee == amount; an error aborts everything and leaves
	// the bounty Open.
	credited, fee, err := ledger.Deposit(winner.String(), b.amount, b.feeBps)
	if err != nil {
		panic(err)
	}
	openTotal -= b.amount // >= 0: openTotal == Σ open amounts >= b.amount
	b.status = StatusAwarded
	b.winner = winner

	chain.Emit("BountyAwarded",
		"id", itoa(id),
		"winner", winner.String(),
		"credited", itoa(credited),
		"fee", itoa(fee),
	)
}

// Cancel closes an open bounty and refunds its escrow to the funder's
// claimable balance, fee-free. Only the bounty's funder may cancel.
// Terminal: a cancelled bounty can never change again.
func Cancel(cur realm, id int64) {
	caller := cur.Previous().Address()
	b := mustGetBounty(id)
	if caller != b.funder {
		panic("only the bounty funder may cancel")
	}
	if b.status != StatusOpen {
		panic("bounty is not open")
	}

	if _, _, err := ledger.Deposit(b.funder.String(), b.amount, 0); err != nil {
		panic(err)
	}
	openTotal -= b.amount
	b.status = StatusCancelled

	chain.Emit("BountyCancelled", "id", itoa(id), "funder", b.funder.String())
}

// Claim sends amount ugnot of the caller's claimable balance (won
// bounties and refunds) back to the caller.
func Claim(cur realm, amount int64) {
	caller := cur.Previous().Address()
	if err := ledger.Withdraw(caller.String(), amount); err != nil {
		panic(err)
	}
	send(cur, caller, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// ClaimAll sends the caller's entire claimable balance back to the
// caller. Fails if there is nothing to claim.
func ClaimAll(cur realm) {
	caller := cur.Previous().Address()
	amount, err := ledger.WithdrawAll(caller.String())
	if err != nil {
		panic(err)
	}
	if amount == 0 {
		panic("nothing to claim")
	}
	send(cur, caller, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// WithdrawFees sends the accrued fee pot to the fee recipient. Only the
// fee recipient may call it.
func WithdrawFees(cur realm) {
	caller := cur.Previous().Address()
	if caller != feeRecipient {
		panic("only the fee recipient may withdraw fees")
	}
	amount := ledger.WithdrawFees()
	if amount == 0 {
		panic("no fees accrued")
	}
	send(cur, feeRecipient, amount)
	chain.Emit("FeesWithdrawn", "to", feeRecipient.String(), "amount", itoa(amount))
}

// SweepDenom sends the surplus of a single denomination to the fee
// recipient (the bounded escape hatch validated on the vault realm).
// For ugnot only the excess over Liabilities() moves; other denoms move
// wholly. Only the fee recipient may call it.
func SweepDenom(cur realm, denom string) {
	caller := cur.Previous().Address()
	if caller != feeRecipient {
		panic("only the fee recipient may sweep surplus")
	}
	if denom == "" {
		panic("empty denom")
	}
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	amount := bk.GetCoin(self, denom)
	if denom == Denom {
		amount -= Liabilities()
	}
	if amount <= 0 {
		panic("no surplus to sweep for " + denom)
	}
	bk.SendCoins(self, feeRecipient, chain.Coins{chain.NewCoin(denom, amount)})
	chain.Emit("SurplusSwept", "to", feeRecipient.String(), "coins", itoa(amount)+denom)
}

// SetFeeBps sets the protocol fee snapshotted into FUTURE bounties at
// creation. Existing bounties keep the fee they were created under.
// Admin only; bounded by [0, MaxFeeBps].
func SetFeeBps(cur realm, bps int64) {
	assertAdmin(cur.Previous().Address())
	if bps < 0 || bps > MaxFeeBps {
		panic("fee bps out of range [0, " + itoa(MaxFeeBps) + "]")
	}
	old := feeBps
	feeBps = bps
	chain.Emit("FeeBpsChanged", "old", itoa(old), "new", itoa(bps))
}

// SetFeeRecipient re-points the fee/surplus role, including the pot
// accrued so far. Admin only; zero address rejected.
func SetFeeRecipient(cur realm, next address) {
	assertAdmin(cur.Previous().Address())
	var zero address
	if next == zero {
		panic("empty fee recipient")
	}
	old := feeRecipient
	feeRecipient = next
	chain.Emit("FeeRecipientChanged", "old", old.String(), "new", next.String())
}

// TransferAdmin hands the admin role to next. Admin only; zero address
// rejected. One-step (documented trade-off, as on the vault).
func TransferAdmin(cur realm, next address) {
	assertAdmin(cur.Previous().Address())
	var zero address
	if next == zero {
		panic("empty admin address")
	}
	admin = next
	chain.Emit("AdminTransferred", "newAdmin", next.String())
}

// --- read-only views ---

// BountyInfo returns a bounty's fields by value: funder, title, amount,
// snapshotted fee bps, status, winner (zero address unless awarded).
func BountyInfo(id int64) (funder address, title string, amount, feeBps int64, status string, winner address) {
	b := mustGetBounty(id)
	return b.funder, b.title, b.amount, b.feeBps, b.status, b.winner
}

// Admin returns the current admin.
func Admin() address { return admin }

// FeeRecipient returns who may withdraw fees and sweep surplus.
func FeeRecipient() address { return feeRecipient }

// FeeBps returns the protocol fee that will be snapshotted into newly
// created bounties (existing bounties keep their own snapshot).
func FeeBps() int64 { return feeBps }

// NumBounties returns how many bounties have ever been created.
func NumBounties() int64 { return nextID }

// OpenTotal returns the escrow held by open bounties (the B term).
func OpenTotal() int64 { return openTotal }

// BalanceOf returns addr's claimable balance (won bounties + refunds).
func BalanceOf(addr address) int64 { return ledger.BalanceOf(addr.String()) }

// UsersTotal returns the sum of all claimable balances (the U term).
func UsersTotal() int64 { return ledger.UsersTotal() }

// FeesAccrued returns the fee pot (the F term).
func FeesAccrued() int64 { return ledger.FeesAccrued() }

// Liabilities returns everything this realm owes:
// openTotal + UsersTotal + FeesAccrued.
func Liabilities() int64 { return openTotal + ledger.Liabilities() }

// Held returns the ugnot actually held at the realm address (the H term).
func Held() int64 { return banker.NewReadonlyBanker().GetCoin(self, Denom) }

// Surplus returns Held() - Liabilities() (the S term; >= 0 unless a
// conservation bug exists).
func Surplus() int64 { return Held() - Liabilities() }

// Address returns this realm's address (the escrow target).
func Address() address { return self }

// Render shows configuration, totals, the composed conservation check,
// and the most recent bounties (bounded page, newest first).
func Render(_ string) string {
	held := Held()
	liab := Liabilities()
	status := "OK"
	if held < liab {
		status = "VIOLATED"
	}
	out := "# Bounties\n\n"
	out += "GNOT bounty board; accounting delegated to p/.../feeledger.\n\n"
	out += "## Configuration\n\n"
	out += "- fee on award: " + itoa(feeBps) + " bps (cap " + itoa(MaxFeeBps) + " bps)\n"
	out += "- fee recipient: " + feeRecipient.String() + "\n"
	out += "- admin: " + admin.String() + "\n\n"
	out += "## Accounting (H == B + U + F + S)\n\n"
	out += "- open escrow (B): " + itoa(openTotal) + Denom + "\n"
	out += "- claimable (U): " + itoa(ledger.UsersTotal()) + Denom + "\n"
	out += "- fees accrued (F): " + itoa(ledger.FeesAccrued()) + Denom + "\n"
	out += "- held (H): " + itoa(held) + Denom + "\n"
	out += "- conservation: " + status + "\n\n"
	out += "## Latest bounties\n\n"
	if nextID == 0 {
		out += "No bounties yet.\n"
		return out
	}
	shown := 0
	bounties.ReverseIterate("", "", func(_ string, v any) bool {
		b := v.(*bounty)
		out += "- #" + itoa(b.id) + " [" + b.status + "] " + b.title +
			" — " + itoa(b.amount) + Denom + "\n"
		shown++
		return shown >= 20
	})
	return out
}

// --- internals ---

func assertAdmin(caller address) {
	if caller != admin {
		panic("admin only")
	}
}

func mustGetBounty(id int64) *bounty {
	v := bounties.Get(padID(id))
	if v == nil {
		panic("unknown bounty id")
	}
	return v.(*bounty)
}

// assertValidTitle bounds length and restricts the charset so titles
// cannot inject markdown into Render output.
func assertValidTitle(title string) {
	if len(title) == 0 || len(title) > maxTitleLen {
		panic("title must be 1-" + strconv.Itoa(maxTitleLen) + " characters")
	}
	for i := 0; i < len(title); i++ {
		c := title[i]
		switch {
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		case c >= '0' && c <= '9':
		case c == ' ' || c == '_' || c == '-':
		default:
			panic("title may only contain letters, digits, space, _ and -")
		}
	}
}

// padID renders an id as a fixed-width key so avl iteration order is
// numeric order.
func padID(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// send moves amount ugnot from the realm to `to`. Callers must have
// debited the ledger first (checks-effects-interactions).
func send(cur realm, to address, amount int64) {
	bk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bk.SendCoins(self, to, chain.Coins{chain.NewCoin(Denom, amount)})
}

func itoa(n int64) string {
	return strconv.FormatInt(n, 10)
}

func checkedAdd(a, b int64) (int64, bool) {
	sum := a + b
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}
